-- Carga do Catálogo da Mudelar (o da Emylia) na organização b6ffce4f-f630-4933-833a-008649757a33, como dados de teste do Catálogo e custos.
-- Gerado por scripts/emylia/gerarCargaCatalogo.ts a partir de src/emylia (seed, custos0, catalogo0, receitaDe).
-- 55 ramos, 16 perfis, 43 equipamentos, 5 custos de estrutura,
-- 367 serviços (753 passos de mão de obra, 1001 usos de equipamento, 1151 usos de consumível, 367 preços),
-- 2167 produtos e 145 consumíveis (por ligar a um fornecedor; a marca e o nome do fornecedor ficam em texto).
-- Só corre se a organização existir. Ids determinísticos e ON CONFLICT DO NOTHING: correr duas vezes não duplica.

SET lock_timeout = '5s';
DO $carga$
DECLARE
  v_org uuid := 'b6ffce4f-f630-4933-833a-008649757a33';
  v_user uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM anew_organizations WHERE id = v_org) THEN
    RAISE NOTICE 'Organização % não existe nesta base: carga do Catálogo ignorada.', v_org;
    RETURN;
  END IF;
  SELECT m.user_id INTO v_user FROM anew_memberships m JOIN anew_users u ON u.id = m.user_id
   WHERE m.organization_id = v_org ORDER BY m.created_at LIMIT 1;
  IF v_user IS NULL THEN RAISE EXCEPTION 'A organização não tem utilizadores (é preciso um para created_by).'; END IF;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
    ON CONFLICT (id) DO NOTHING;
END $carga$;
RESET lock_timeout;
